import json
import sys
import uuid

LEVELS = ["off", "minimal", "low", "medium", "high", "xhigh"]
MODELS = [
    ("openrouter/google/gemini-4-neon", "openrouter/Google: Gemini 4 Neon"),
    ("anthropic/claude-opus-5-5", "anthropic/Claude Opus 5.5"),
    ("openai-codex/gpt-6-luna", "openai-codex/GPT-6 Luna"),
]


def send(message):
    sys.stdout.write(json.dumps(message) + "\n")
    sys.stdout.flush()


def session_new():
    return {
        "sessionId": str(uuid.uuid4()),
        "configOptions": [
            {"type": "select", "id": "model", "category": "model", "name": "Model",
             "description": "Select the model for this session", "currentValue": MODELS[0][0],
             "options": [{"value": v, "name": n, "description": None} for v, n in MODELS]},
            {"type": "select", "id": "thought_level", "category": "thought_level", "name": "Thinking",
             "description": "Select the thinking level", "currentValue": "medium",
             "options": [{"value": v, "name": v, "description": None} for v in LEVELS]},
        ],
        "models": {"currentModelId": MODELS[0][0],
                   "availableModels": [{"modelId": v, "name": n, "description": None} for v, n in MODELS]},
        "modes": {"currentModeId": "medium",
                  "availableModes": [{"id": v, "name": f"Thinking: {v}", "description": None} for v in LEVELS]},
    }


for line in sys.stdin:
    try:
        msg = json.loads(line)
    except ValueError:
        continue
    method, rid = msg.get("method"), msg.get("id")
    if rid is None:
        continue
    if method == "initialize":
        send({"jsonrpc": "2.0", "id": rid, "result": {
            "protocolVersion": 1,
            "agentInfo": {"name": "pi-acp", "title": "pi ACP adapter", "version": "0.0.33"},
            "agentCapabilities": {"loadSession": True, "promptCapabilities": {"image": True}},
        }})
    elif method == "session/new":
        send({"jsonrpc": "2.0", "id": rid, "result": session_new()})
    elif method == "session/prompt":
        sid = msg.get("params", {}).get("sessionId")
        send({"jsonrpc": "2.0", "method": "session/update", "params": {"sessionId": sid, "update": {
            "sessionUpdate": "agent_message_chunk", "content": {"type": "text", "text": "Hi from Pi."}}}})
        send({"jsonrpc": "2.0", "id": rid, "result": {"stopReason": "end_turn"}})
    else:
        send({"jsonrpc": "2.0", "id": rid, "result": {}})
